  Node node(){return root;}
  private void refresh(boolean more){
    if(more){if(edges.size()>=2000||nodes.size()>=500&&!cursor.startsWith("E:")){showFragmentWarning();return;}if(cursor.isEmpty()){status.setText("Все полученные страницы показаны.");return;}}
    if(!more){cursor="";nodes.clear();edges.clear();truncatedNodes=false;truncatedEdges=false;showFragmentWarning();graph.data(List.of(),List.of());list.getItems().clear();tree.setRoot(null);preview.getChildren().clear();selected=null;}
    api.call("content.library.graph",obj("cursor",cursor,"limit",nodes.size()>=500?1:100,"query",query.getText(),"type",type.getSelectionModel().getSelectedIndex()==0?"":type.getValue(),"organization",organization.getText(),"from",dateMillis(date.getText())),status,r->{
      Set<String> known=new HashSet<>();for(JsonObject node:nodes)known.add(str(node,"id"));for(JsonObject node:items(r,"nodes")){String id=str(node,"id");if(known.contains(id))continue;if(nodes.size()<500){known.add(id);nodes.add(node);}else truncatedNodes=true;}
      Set<String> knownEdges=new HashSet<>();for(JsonObject edge:edges)knownEdges.add(str(edge,"id"));for(JsonObject edge:items(r,"edges")){String id=str(edge,"id");if(!knownEdges.add(id))continue;if(edges.size()<2000&&known.contains(str(edge,"from"))&&known.contains(str(edge,"to")))edges.add(edge);else truncatedEdges=true;}
      cursor=str(r,"nextCursor");showFragmentWarning();graph.data(nodes,edges);autoAnalyze();list.getItems().setAll(nodes);TreeItem<JsonObject> parent=new TreeItem<>(obj("title","Материалы"));Map<String,TreeItem<JsonObject>> topics=new LinkedHashMap<>();for(JsonObject node:nodes){String topic=topic(node);TreeItem<JsonObject> group=topics.computeIfAbsent(topic,k->{TreeItem<JsonObject> t=new TreeItem<>(obj("title",k));parent.getChildren().add(t);t.setExpanded(true);return t;});group.getChildren().add(new TreeItem<>(node));}tree.setRoot(parent); });
  }
  private void showFragmentWarning(){boolean bounded=truncatedNodes||truncatedEdges||nodes.size()>=500||edges.size()>=2000;fragmentWarning.setManaged(bounded);fragmentWarning.setVisible(bounded);if(!bounded){fragmentWarning.setText("");return;}String text=truncatedNodes||truncatedEdges?"Показана только часть доступного графа.":"Достигнут предел текущего вида графа.";text+=" Отображается узлов: "+nodes.size()+" из предела 500; связей: "+edges.size()+" из предела 2000. ";text+=nodes.size()>=500&&edges.size()<2000&&cursor.startsWith("E:")?"Можно дозагрузить связи между показанными узлами. Для других материалов уточните поиск или фильтры.":"Уточните поиск или фильтры, чтобы увидеть другую часть графа.";fragmentWarning.setText(text);}
  private void autoAnalyze(){if(nodes.size()<2)return;List<JsonObject> sample=nodes.stream().limit(4).toList();String signature=sample.stream().map(node->str(node,"id")+":"+number(node,"revision")).collect(java.util.stream.Collectors.joining(";"));if(signature.equals(lastAutomaticAnalysis))return;lastAutomaticAnalysis=signature;JsonArray ids=new JsonArray();for(JsonObject node:sample)ids.add(str(node,"id"));api.call("agent.library.suggest",obj("ids",ids),null,result->{/* Only the approved local model runs; proposals remain unconfirmed until an editor decides. */});}
  private String topic(JsonObject node){String id=str(node,"id");for(JsonObject edge:edges){String related=str(edge,"from").equals(id)?str(edge,"to"):str(edge,"to").equals(id)?str(edge,"from"):"";if(!related.isBlank())for(JsonObject candidate:nodes)if(str(candidate,"id").equals(related)&&str(candidate,"type").equals("TOPIC"))return title(candidate);}String kind=str(node,"type");String label=type.getConverter().toString(kind);return label==null||label.isBlank()?"Материалы":label;}
  void openId(String id){if(id!=null&&id.matches("[A-Za-z0-9_-]{1,80}"))open(obj("id",id));}
  private void documentLink(String link){if(link.startsWith("aegis-library:"))openId(link.substring("aegis-library:".length()));else api.openLink.accept(link);}
  private void open(JsonObject node){api.call("content.library.get",obj("id",str(node,"id")),status,value->{selected=value;preview.getChildren().setAll(heading(title(value)),label("Версия "+number(value,"revision")+" · "+NewsView.state(str(value,"state"))),DocumentEditor.render(str(value,"body"),this::documentLink),actions(button("Изменить",()->edit(value)),button("История версий",()->history(value)),button("Экспорт Markdown",()->exportMaterial(value)),button("На проверку",()->change("content.library.submit",value,obj())),button("Опубликовать",()->change("content.library.publish",value,obj()))),relations(value));preview.getChildren().add(MaterialFiles.node(api,value,status,()->open(value)));});}
  private Node relations(JsonObject value){TextField target=field("Идентификатор связанного материала"),reason=field("Основание связи");VBox proposals=new VBox(8);Runnable refresh=()->api.call("content.library.link.list",obj("id",str(value,"id"),"limit",100),status,r->{proposals.getChildren().clear();for(JsonObject edge:items(r,"items")){String state=str(edge,"state");VBox item=card(label(str(edge,"ai").equals("true")?"Предложение ИИ":"Связь материалов"),label(str(edge,"explanation")),label(switch(state){case "PROPOSED"->"Ожидает подтверждения";case "APPROVED"->"Подтверждена";default->"Отклонена";}));if(state.equals("PROPOSED"))item.getChildren().add(actions(button("Подтвердить",()->decide(edge,"APPROVE")),button("Отклонить",()->decide(edge,"REJECT"))));proposals.getChildren().add(item);}});VBox body=card(target,reason,button("Предложить связь",()->api.call("content.library.link.propose",obj("from",str(value,"id"),"to",target.getText(),"explanation",reason.getText()),status,r->refresh.run())),button("Предложить связи с помощью ИИ",()->{JsonArray ids=new JsonArray();ids.add(str(value,"id"));for(JsonObject node:nodes)if(ids.size()<5&&!str(node,"id").equals(str(value,"id")))ids.add(str(node,"id"));api.call("agent.library.suggest",obj("ids",ids),status,r->{String job=str(r,"jobId");if(job.isEmpty())refresh.run();else pollSuggestion(job,proposals,refresh,0);});}),proposals);refresh.run();return fold("Связи и предложения",body);}
  private void pollSuggestion(String job,VBox visible,Runnable refresh,int attempt){if(attempt>=30){status.setText("Анализ продолжается. Обновите предложения позже.");return;}status.setText("ИИ анализирует разрешённые материалы…");javafx.animation.PauseTransition delay=new javafx.animation.PauseTransition(javafx.util.Duration.seconds(2));delay.setOnFinished(e->{if(visible.getScene()==null)return;api.call("agent.library.suggestion.get",obj("jobId",job),status,result->{String state=str(result,"state");if(state.equals("DONE")){status.setText("Предложения готовы. Постоянные связи требуют подтверждения редактора.");refresh.run();}else if(state.equals("FAILED"))status.setText("Локальная модель не смогла подготовить предложения. Повторите позже.");else pollSuggestion(job,visible,refresh,attempt+1);});});delay.play();}
