  private void edit(JsonObject value){TextField title=field("Название материала");title.setText(value==null?"":str(value,"title"));ComboBox<String> kind=new ComboBox<>();kind.getItems().setAll("NOTE","ARTICLE","DOCUMENT","PDF","IMAGE","VIDEO","PERSON","ORGANIZATION","TOPIC");kind.setValue(value==null?"NOTE":str(value,"type"));kind.setConverter(type.getConverter());DocumentEditor editor=new DocumentEditor(this::documentLink);editor.text(value==null?"":str(value,"body"));MaterialPolicyEditor policy=new MaterialPolicyEditor(value,organization.getText());VBox form=card(heading("Редактор библиотеки"),title,kind,editor.node(),policy.node(),button("Сохранить черновик",()->{JsonObject args=obj("title",title.getText(),"body",editor.text(),"type",kind.getValue(),"organization",organization.getText(),"policy",policy.value());if(value!=null){args.remove("organization");args.remove("type");args.addProperty("id",str(value,"id"));args.addProperty("revision",number(value,"revision"));}api.call("content.library."+(value==null?"create":"update"),args,status,r->{open(r);refresh(false);});}));if(value!=null)form.getChildren().add(MaterialFiles.node(api,value,status,()->open(value)));preview.getChildren().setAll(form);}
  private void exportMaterial(JsonObject value){api.call("content.library.export",obj("id",str(value,"id")),status,result->{InWindowFileChooser chooser=new InWindowFileChooser();chooser.setTitle("Экспорт разрешённого материала");chooser.setInitialFileName("Материал.md");java.io.File target=chooser.showSaveDialog((Stage)root.getScene().getWindow());if(target==null)return;String text=str(result,"text");api.task(()->{java.nio.file.Files.writeString(target.toPath(),text,java.nio.charset.StandardCharsets.UTF_8,java.nio.file.StandardOpenOption.CREATE_NEW);return true;},status,r->status.setText("Разрешённый материал экспортирован."));});}
  private void history(JsonObject value){historyPage(value,0);}
